#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         vector<ll> a(n);        for (auto &x : a) cin >> x;         sort(a.begin(), a.end());                int mx = a[n - 1];                        vector<ll>b , c;                for(auto it : a){            if(it != mx){                b.push_back(it);            }else{                c.push_back(it);            }        }                if(b.size() == 0){            cout << -1 << endl;             continue;        }        else{            cout << b.size() << " " << c.size() << endl;            for(auto it : b){                cout << it << " " ;            }            cout << endl;            for(auto it : c){                cout << it << " " ;            }                        cout << endl ;        }     }     return 0;}